'use strict';
const catSymbol=(cls='')=>`<svg class="cat-symbol ${cls}" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M6 14 5 5l9 5h4l9-5-1 10c3 10-2 14-10 14S2 24 6 14Z" fill="currentColor" opacity=".15"/><path d="m6 14-1-9 9 5h4l9-5-1 9c3 9-2 14-10 14S3 23 6 14Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><path d="M11 17v2m10-2v2m-7 3 2 2 2-2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`;
window.auraCatSymbol=catSymbol;
const oldSpaceToggle=$('#space-toggle').onclick;$('#space-toggle').onclick=()=>{oldSpaceToggle();if(document.body.classList.contains('drawer-open'))$('#space-drawer nav a').focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#space-toggle').focus();});
$('.quiet-brand').innerHTML=catSymbol()+'<span class="brand-word">aura</span>';
$('#space-toggle').innerHTML=catSymbol()+'<span>Your space</span>';
$('#space-drawer .brand').innerHTML=catSymbol()+'<span>aura</span>';
$('#space-drawer .little-plant').innerHTML=catSymbol();
const sideNav=$('#space-drawer nav');sideNav.insertAdjacentHTML('beforeend','<a href="#logs">'+catSymbol()+'<span>Conversation logs</span></a><a href="#preferences">'+catSymbol()+'<span>Memory & country</span></a>');
sideNav.querySelector('a[href="#sessions"]')?.remove();
sideNav.querySelectorAll('a').forEach(a=>{const span=a.querySelector('span');if(span)a.innerHTML=catSymbol()+span.outerHTML;});
const scrim=document.createElement('button');scrim.className='space-scrim';scrim.setAttribute('aria-label','Close Your space');scrim.tabIndex=-1;document.body.append(scrim);scrim.onclick=()=>{document.body.classList.remove('drawer-open');$('#space-drawer').inert=true;$('#space-toggle').setAttribute('aria-expanded','false');$('#space-toggle').focus();};
sideNav.addEventListener('click',e=>{if(e.target.closest('a'))scrim.onclick();});
state.persist=false;
let journalDraft=null,journalSearch='',journalTimer=null,selectedLog=null;
function prefs(){state.preferences={country:'',journalMemory:false,...state.preferences};state.chatLogs=Array.isArray(state.chatLogs)?state.chatLogs:[];return state.preferences;}
function tokenWords(text){return [...new Set(String(text).toLowerCase().normalize('NFKD').match(/[\p{L}\p{N}]{3,}/gu)||[])].map(x=>x.replace(/(?:ing|ed|s)$/,''));}
const memoryStop=new Set('the and that with have this from what about just like know wrote journal entry remember been was were for are not but you your mine today yesterday feel feeling'.split(' '));
function pickJournalExcerpts(query,entries){const words=tokenWords(query).filter(x=>!memoryStop.has(x));return entries.filter(e=>e.memory!==false&&typeof e.text==='string').map((e,i)=>{const hay=(e.title+' '+e.text).toLowerCase(),matches=words.filter(w=>hay.includes(w));return {entry:e,score:matches.length*10+i/Math.max(entries.length,1),match:matches[0]};}).sort((a,b)=>b.score-a.score).slice(0,4).map(({entry:e,match})=>{const pos=match?e.text.toLowerCase().indexOf(match):0,start=Math.max(0,pos-500),text=e.text.slice(start,start+2100);return {title:String(e.title||'Journal entry').slice(0,160),date:String(e.date||'').slice(0,50),text:(start?'[… excerpt …] ':'')+text};});}
const countryCodes='AF AL DZ AS AD AO AI AQ AG AR AM AW AU AT AZ BS BH BD BB BY BE BZ BJ BM BT BO BQ BA BW BV BR IO BN BG BF BI CV KH CM CA KY CF TD CL CN CX CC CO KM CG CD CK CR CI HR CU CW CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FK FO FJ FI FR GF PF TF GA GM GE DE GH GI GR GL GD GP GU GT GG GN GW GY HT HM VA HN HK HU IS IN ID IR IQ IE IM IL IT JM JP JE JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MO MG MW MY MV ML MT MH MQ MR MU YT MX FM MD MC MN ME MS MA MZ MM NA NR NP NL NC NZ NI NE NG NU NF MK MP NO OM PK PW PS PA PG PY PE PH PN PL PT PR QA RE RO RU RW BL SH KN LC MF PM VC WS SM ST SA SN RS SC SL SG SX SK SI SB SO ZA GS SS ES LK SD SR SJ SE CH SY TW TJ TZ TH TL TG TK TO TT TN TR TM TC TV UG UA AE GB US UM UY UZ VU VE VN VG VI WF EH YE ZM ZW'.split(' ');
const regionNames=new Intl.DisplayNames([navigator.language||'en'],{type:'region'});
const countries=countryCodes.map(code=>({code,name:regionNames.of(code)})).sort((a,b)=>a.name.localeCompare(b.name));
window.auraChatContext=query=>{const p=prefs(),context={};if(p.journalMemory)context.journal=pickJournalExcerpts(query,state.entries);if(p.country){const country=countries.find(c=>c.code===p.country);if(country)context.country=country;}return context;};
const baseChatPage=chatPage;
chatPage=function(){const p=prefs();let html=baseChatPage().replace('<span class="quiet-mark" aria-hidden="true">✳</span>',catSymbol('quiet-mark')).replaceAll('<span class="message-label">aura</span>','<span class="message-label">'+catSymbol()+'aura</span>');html=html.replace('Chat stays in this tab unless you save it.','When private logs are unlocked, chats save encrypted on this computer. Optional journal memory and country are included only if enabled.');return html.replace('<div class="quiet-chat-actions">','<div class="quiet-chat-actions"><a class="memory-link" href="#preferences">'+(p.journalMemory?'Journal memory on':'Memory off')+(p.country?' · '+esc(regionNames.of(p.country)):'')+'</a>');};
function newJournalDraft(){return {id:crypto.randomUUID(),title:'',text:'',date:stamp(),memory:true};}
function journalListHTML(){const entries=state.entries.slice().reverse().filter(e=>(e.title+' '+e.text).toLowerCase().includes(journalSearch.toLowerCase()));return entries.length?entries.map(e=>`<button class="journal-page ${journalDraft?.id===e.id?'chosen':''}" data-journal-open="${esc(e.id)}"><span class="page-date">${niceDate(e.date)}</span><strong>${esc(e.title||'Untitled page')}</strong><span class="page-excerpt">${esc(e.text.slice(0,85))}</span></button>`).join(''):'<p class="journal-empty">'+(journalSearch?'No matching pages.':'Your first page starts here.')+'</p>';}
function journalPage(){if(!journalDraft)journalDraft=newJournalDraft();return `<div class="journal-heading"><div><p class="eyebrow">YOUR WORDS, YOUR PACE</p><h1>A quiet place to leave things.</h1></div><button class="secondary" data-journal-new>New page +</button></div><div class="journal-workspace"><div class="journal-index"><label class="sr-only" for="journal-search">Search your pages</label><input id="journal-search" type="search" placeholder="Find a page…" value="${esc(journalSearch)}"><div id="journal-list">${journalListHTML()}</div></div><article class="journal-paper"><div class="journal-paper-top"><span>${new Date(journalDraft.date).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</span><span class="journal-save-status" role="status">${vaultKey?'Encrypted autosave on':'Autosave in this tab'}</span></div><label class="sr-only" for="journal-title">Page title</label><input id="journal-title" maxlength="160" placeholder="Give today a title…" value="${esc(journalDraft.title)}"><label class="sr-only" for="journal-text">Your journal</label><textarea id="journal-text" maxlength="30000" placeholder="What’s taking up space in your mind?\n\nStart anywhere. This is just for you.">${esc(journalDraft.text)}</textarea><div class="journal-paper-bottom"><span id="journal-words">${journalDraft.text.trim()?journalDraft.text.trim().split(/\s+/).length:0} words</span><label class="journal-memory"><input id="entry-memory" type="checkbox" ${journalDraft.memory!==false?'checked':''}> Available to journal memory ${prefs().journalMemory?'':'(currently off)'}</label><button class="icon-delete" data-journal-delete="${esc(journalDraft.id)}" aria-label="Delete this page">Delete</button></div></article></div><p class="storage-caption vault-status">${esc(vaultStatus)}</p><a class="text-link" href="#logs">${vaultKey?'Your private logs':'Set up or unlock private saving'} →</a>`;}
function storeJournalDraft(){clearTimeout(journalTimer);if(!journalDraft||(!journalDraft.title.trim()&&!journalDraft.text.trim()))return;const i=state.entries.findIndex(e=>e.id===journalDraft.id),entry={...journalDraft,title:journalDraft.title.trim()||'Untitled page',updated:stamp()};if(i>=0)state.entries[i]=entry;else state.entries.push(entry);save();const list=$('#journal-list');if(list)list.innerHTML=journalListHTML();const status=$('.journal-save-status');if(status)status.textContent=vaultKey?'Saving encrypted…':'Saved in this tab';}
function preferencesPage(){const p=prefs();return `<div class="preferences narrow"><h1>Your space, your choices.</h1><section class="preference-section"><h2>Journal memory</h2><p>When enabled, Aura can refer to up to four relevant journal excerpts in a reply. Those excerpts are sent to Google Gemini alongside your chat. This is retrieval, not model training.</p><label class="check"><input id="journal-memory" type="checkbox" ${p.journalMemory?'checked':''}><span>Let Aura use my journal in chat</span></label><p class="small">Exclude any page using its memory checkbox. Turning this off prevents future sharing; it cannot recall data already sent to the provider.</p></section><section class="preference-section"><h2>Where should advice fit?</h2><p>Choose your country for relevant context. No GPS, IP lookup, or precise location is collected. Your selected country is shared with Gemini when you send a chat.</p><label for="aura-country">Country or region</label><select id="aura-country"><option value="">Don’t share a country</option>${countries.map(c=>`<option value="${c.code}" ${p.country===c.code?'selected':''}>${esc(c.name)}</option>`).join('')}</select><p class="small">Location context doesn’t verify services or eligibility. Aura should never invent local helplines or contact details.</p></section><section class="preference-section"><h2>Decorative cats</h2><p>Quiet company, with no messages or rewards.</p><label for="cat-count">Cats on screen</label><select id="cat-count"><option value="1" ${p.catCount===1?'selected':''}>One cat</option><option value="2" ${p.catCount!==1?'selected':''}>Two cats</option></select></section><section class="preference-section"><h2>Private saving</h2><p class="vault-status">${esc(vaultStatus)}</p><a class="secondary" href="#logs">Open logs & private storage</a></section></div>`;}
function vaultFormHTML(){return `<form id="vault-form" class="vault-form"><div class="vault-icon">${catSymbol()}</div><h2>${vaultExists?'Your space is locked.':'Keep your space private.'}</h2><p>${vaultExists?'Enter your passphrase to restore your journal and conversation logs.':'Set a passphrase to encrypt journal entries and automatically save every conversation on this computer.'}</p><label for="vault-passphrase">Passphrase</label><input id="vault-passphrase" type="password" autocomplete="${vaultExists?'current-password':'new-password'}" ${vaultExists?'':'minlength="12"'} required placeholder="${vaultExists?'Your private passphrase':'At least 12 characters'}">${vaultExists?'':'<label for="vault-confirm">Confirm passphrase</label><input id="vault-confirm" type="password" autocomplete="new-password" required minlength="12">'}<p id="vault-form-error" class="form-error" role="alert"></p><button class="primary" id="vault-submit">${vaultExists?'Unlock my space':'Create encrypted storage'}</button><p class="small">The passphrase never leaves this browser. There is no passphrase recovery. Protect it carefully.</p></form>`;}
function logsPage(){prefs();return `<div class="logs-heading"><div><p class="eyebrow">CONVERSATIONS, KEPT GENTLY</p><h1>Your logs.</h1></div>${vaultKey?'<button class="secondary" data-vault-lock>Lock my space</button>':''}</div><p class="storage-caption vault-status">${esc(vaultStatus)}</p>${vaultError?`<div class="notice" role="alert">${esc(vaultError)} <button class="secondary" data-vault-reload>Lock without saving</button></div>`:''}${!vaultKey?(vaultExists===null?'<p class="journal-empty">Checking encrypted storage…</p>':vaultFormHTML()):`<div class="logs-layout"><div class="log-index">${state.chatLogs.length?state.chatLogs.slice().reverse().map(log=>`<button data-log-open="${esc(log.id)}" class="log-item ${selectedLog===log.id?'chosen':''}"><strong>${esc(log.title)}</strong><span>${niceDate(log.updated)} · ${log.messages.filter(m=>m.role==='user').length} messages</span></button>`).join(''):'<p class="journal-empty">Every conversation will appear here automatically.</p>'}</div><div class="log-reading">${logReadingHTML()}</div></div>`}<details class="vault-explanation"><summary>What private saving protects</summary><p>Aura encrypts journal entries, logs, and preferences with AES-256-GCM in your browser. A key is derived from your passphrase with PBKDF2-SHA-256 (600,000 iterations). Only encrypted data is written to <code>.aura-data/vault.json</code> on this computer.</p><p>This protects the saved file from casual reading. Someone controlling your device or browser while Aura is unlocked could still read your content. Browser extensions, weak passphrases, malware and provider-retained chat data are outside this protection. This is one local vault, not a multi-user account system.</p><p>New messages and journal changes are saved automatically while unlocked. Before unlocking, new work is temporary in this tab. Encrypted backups may be exported below; readable exports contain sensitive text.</p></details><div class="actions"><button class="secondary" data-vault-export>Export encrypted backup</button><button class="secondary" data-action="export">Export readable data</button></div>`;}
function logReadingHTML(){const log=state.chatLogs.find(l=>l.id===selectedLog);if(!log)return '<div class="log-empty">'+catSymbol()+'<p>A conversation to come back to.</p></div>';return `<div class="log-reading-head"><span>${esc(log.title)}</span><div><button class="secondary" data-log-resume="${esc(log.id)}">Continue chat</button><button class="icon-delete" data-log-delete="${esc(log.id)}">Delete</button></div></div>${log.messages.map(m=>`<div class="log-message ${m.role}"><small>${m.role==='user'?'You':'Aura · AI'}</small><p>${esc(m.text)}</p></div>`).join('')}`;}
function settingsPage(){return `<div class="preferences narrow"><h1>Aura, explained simply.</h1><section class="preference-section"><h2>Your data</h2><p>Journal and chats are temporary until you unlock encrypted private saving. Conversations are automatically logged while unlocked. Choose which journal entries may inform AI replies, and whether to share a country.</p><div class="actions"><a class="secondary" href="#preferences">Memory & country</a><a class="secondary" href="#logs">Private logs</a></div></section><section class="preference-section"><h2>AI support, with limits</h2><p>Aura uses Google Gemini for conversational self-help. It isn’t a person, a therapist, diagnosis, or emergency care. AI can misunderstand you and repeat itself. No clinician monitors your conversations. The product has not undergone clinical validation.</p><p>The chat and any authorized journal excerpts and country context are sent to Google when you send a message. Encryption of the local file does not change the AI provider’s data handling. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Provider terms</a>.</p></section><section class="preference-section"><h2>The cats</h2><p>Two original SVG characters, Miso and Mochi, use an animation state machine. Mood changes how often they rest or play; it doesn’t diagnose you. Motion is optional. There are always at most two, with no streaks or rewards tied to emotional distress.</p></section><section class="preference-section"><h2>Psychological approaches</h2><p>Original self-help prompts draw on CBT, behavioural activation, values work and problem-solving. <a href="https://www.nice.org.uk/guidance/ng222/chapter/recommendations" target="_blank" rel="noopener noreferrer">NICE guidance</a> and <a href="https://www.who.int/publications/i/item/9789240003927" target="_blank" rel="noopener noreferrer">WHO self-help guidance</a> inform those approaches; they do not endorse Aura.</p></section><section class="preference-section"><h2>Clear this space</h2><p>Remove Aura data from this tab and browser. If your vault is unlocked, the empty state will also be saved encrypted. This does not remove exports, backups, or data retained by the AI provider. A locked vault is unaffected.</p><button class="secondary" data-action="clear">Delete my Aura data</button></section></div>`;}
const featureRoute=route;let previousFeaturePage='';
route=function(){const page=location.hash.slice(1)||'chat';const views={journal:journalPage,preferences:preferencesPage,logs:logsPage,settings:settingsPage};if(views[page]){document.body.classList.remove('is-chat');$('#main').innerHTML=views[page]();bindFeatureForms(page);renderCats();}else featureRoute();if(previousFeaturePage!==page){$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');previousFeaturePage=page;}document.querySelectorAll('#space-drawer nav a').forEach(a=>a.classList.toggle('active',a.hash===location.hash));};
function bindFeatureForms(page){if(page==='journal'){$('#journal-search').addEventListener('input',e=>{journalSearch=e.target.value;$('#journal-list').innerHTML=journalListHTML();});for(const id of ['journal-title','journal-text','entry-memory'])$('#'+id).addEventListener('input',()=>{journalDraft.title=$('#journal-title').value;journalDraft.text=$('#journal-text').value;journalDraft.memory=$('#entry-memory').checked;$('#journal-words').textContent=(journalDraft.text.trim()?journalDraft.text.trim().split(/\s+/).length:0)+' words';clearTimeout(journalTimer);journalTimer=setTimeout(storeJournalDraft,450);});}if(page==='preferences'){$('#journal-memory').onchange=e=>{prefs().journalMemory=e.target.checked;save();toast(e.target.checked?'Journal memory enabled.':'Journal sharing turned off.');};$('#cat-count').onchange=e=>{prefs().catCount=Number(e.target.value);save();renderCats();};$('#aura-country').onchange=e=>{prefs().country=e.target.value;save();toast('Country preference updated.');};}if(page==='logs'&&!vaultKey&&$('#vault-form')){$('#vault-form').onsubmit=async e=>{e.preventDefault();const pass=$('#vault-passphrase').value,confirmation=$('#vault-confirm')?.value;$('#vault-form-error').textContent='';$('#vault-submit').disabled=true;try{await openAuraVault(pass,confirmation);}catch(error){$('#vault-form-error').textContent=error.message;$('#vault-submit').disabled=false;}finally{const field=$('#vault-passphrase');if(field)field.value='';const confirm=$('#vault-confirm');if(confirm)confirm.value='';}};}}
const rawSendChat=sendChat;
sendChat=async function(retry=false){const pending=rawSendChat(retry);syncAuraLog();window.auraPersist();await pending;syncAuraLog();window.auraPersist();};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-journal-new')){storeJournalDraft();journalDraft=newJournalDraft();route();$('#journal-title').focus();}
 if(b.dataset.journalOpen){storeJournalDraft();journalDraft={...state.entries.find(x=>x.id===b.dataset.journalOpen)};route();}
 if(b.dataset.journalDelete&&confirm('Delete this journal page? Backups and already shared AI context are unaffected.')){clearTimeout(journalTimer);state.entries=state.entries.filter(x=>x.id!==b.dataset.journalDelete);journalDraft=newJournalDraft();save();route();}
 if(b.dataset.chat==='new'&&chatMessages.length===0){activeLogId=crypto.randomUUID();window.auraPersist();}
 if(b.dataset.logOpen){selectedLog=b.dataset.logOpen;route();}
 if(b.dataset.logResume){const log=state.chatLogs.find(x=>x.id===b.dataset.logResume);if(log&&!chatBusy){syncAuraLog();activeLogId=log.id;chatMessages=log.messages.map(x=>({...x}));chatDraft='';chatError='';save();location.hash='chat';}}
 if(b.dataset.logDelete&&confirm('Delete this conversation log? Exported files and provider data are unaffected.')){state.chatLogs=state.chatLogs.filter(x=>x.id!==b.dataset.logDelete);if(activeLogId===b.dataset.logDelete){chatMessages=[];chatDraft='';activeLogId=crypto.randomUUID();}selectedLog=null;save();route();}
 if(b.hasAttribute('data-vault-reload')&&confirm('Discard unsaved in-tab changes and lock? Export readable data first if you need to keep those changes.')){await lockAuraVault(true);journalDraft=null;}
 if(b.hasAttribute('data-vault-lock'))try{storeJournalDraft();await lockAuraVault();journalDraft=null;}catch(error){toast(error.message);}
 if(b.hasAttribute('data-vault-export'))try{if(vaultKey)await flushAuraVault();const data=await auraLocalAPI('/api/vault');if(!data.exists){toast('Set up encrypted saving first.');return;}const url=URL.createObjectURL(new Blob([JSON.stringify(data.vault)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='aura-encrypted-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}
});
window.auraAfterClear=()=>queueMicrotask(()=>{state.chatLogs=[];state.preferences={country:'',journalMemory:false};journalDraft=null;activeLogId=crypto.randomUUID();save();});
window.addEventListener('hashchange',()=>{clearTimeout(journalTimer);storeJournalDraft();document.body.classList.remove('drawer-open');$('#space-drawer').inert=true;$('#space-toggle').setAttribute('aria-expanded','false');});
route();

window.auraClearTransient=function(){journalDraft=null;journalSearch='';selectedLog=null;};
